        }
        if (_xWindow != 0)
        {
            XDestroyWindow(_xDisplay, _xWindow);
        }

#elif defined(__APPLE__)

        if (_contextHandle != 0)
        {
            NSOpenGLDestroyCurrentContext(&_contextHandle);
        }

#endif
    }
}

